import React, { useState, useEffect, useContext } from 'react';
import { Sun, Moon, Globe, Menu, X, ChevronDown, User, LogIn, UserPlus, Search, Bell } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { LanguageContext } from './../../../../contexts/LanguageContext';

const Header = ({ isAuthenticated = false, onLogout, currentUser = null }) => {
  const navigate = useNavigate();
  const { language, setLanguage, t } = useContext(LanguageContext);

  // États
  const [darkMode, setDarkMode] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [languageDropdownOpen, setLanguageDropdownOpen] = useState(false);
  const [themeDropdownOpen, setThemeDropdownOpen] = useState(false);
  const [userDropdownOpen, setUserDropdownOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [showSearchBar, setShowSearchBar] = useState(false);
  const [searchSuggestions, setSearchSuggestions] = useState([]);
  const [hasNotifications, setHasNotifications] = useState(false);

  // Récupérer les données utilisateur
  const userEmail = currentUser?.email || '';
  const userName = currentUser?.first_name || currentUser?.name || userEmail.split('@')[0] || 'User';

  // Navigation items
  const navItems = [
    { key: 'home', path: '/' },
    { key: 'check', path: '/check' },
    { key: 'learn', path: '/learn' },
    { key: 'about', path: '/about' },
    { key: 'trending', path: '/trending' }
  ];

  // Suggestions de recherche populaires (en fonction de la langue)
  const popularSearches = {
    mg: [
      "Vaovao momba ny cyclona",
      "Fanafody nentim-paharazana",
      "Fivarotana an-tserasera",
      "Fampidirana vaksiny",
      "Fomba fijery mangina"
    ],
    fr: [
      "Info cyclonique",
      "Médecine traditionnelle",
      "Arnaque en ligne",
      "Vaccination COVID",
      "Pensée critique"
    ],
    en: [
      "Cyclone information",
      "Traditional medicine",
      "Online scam",
      "COVID vaccination",
      "Critical thinking"
    ]
  };

  // Initialiser le mode sombre
  useEffect(() => {
    const storedTheme = localStorage.getItem('theme');
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (storedTheme === 'dark' || (!storedTheme && systemPrefersDark)) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    // Simuler des notifications (à remplacer par une API réelle)
    if (isAuthenticated) {
      setHasNotifications(Math.random() > 0.5);
    }
  }, [isAuthenticated]);

  // Gérer la recherche
  useEffect(() => {
    if (searchQuery.length > 2) {
      const suggestions = popularSearches[language]?.filter(item =>
        item.toLowerCase().includes(searchQuery.toLowerCase())
      ).slice(0, 5);
      setSearchSuggestions(suggestions || []);
    } else {
      setSearchSuggestions([]);
    }
  }, [searchQuery, language]);

  // Changer le mode sombre/clair
  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);

    if (newDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  // Changer de langue
  const changeLanguage = (lang) => {
    setLanguage(lang);
    setLanguageDropdownOpen(false);
  };

  // Changer le thème
  const changeTheme = (theme) => {
    if (theme === 'system') {
      localStorage.removeItem('theme');
      const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      setDarkMode(systemPrefersDark);
      if (systemPrefersDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    } else {
      const newDarkMode = theme === 'dark';
      setDarkMode(newDarkMode);
      localStorage.setItem('theme', theme);
      if (newDarkMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
    setThemeDropdownOpen(false);
  };

  // Gérer la recherche
  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      navigate(`/search?q=${encodeURIComponent(searchQuery)}`);
      setSearchQuery('');
      setShowSearchBar(false);
      setSearchSuggestions([]);
    }
  };

  const handleSearchSuggestionClick = (suggestion) => {
    setSearchQuery(suggestion);
    navigate(`/search?q=${encodeURIComponent(suggestion)}`);
    setShowSearchBar(false);
    setSearchSuggestions([]);
  };

  const handleClearSearch = () => {
    setSearchQuery('');
    setSearchSuggestions([]);
  };

  // Navigation functions
  const handleLoginClick = () => {
    navigate('/login');
    setMobileMenuOpen(false);
  };

  const handleRegisterClick = () => {
    navigate('/register');
    setMobileMenuOpen(false);
  };

  const handleLogout = () => {
    if (onLogout) {
      onLogout();
    }
    setUserDropdownOpen(false);
    setMobileMenuOpen(false);
    navigate('/');
  };

  const handleDashboardClick = () => {
    if (currentUser?.role === 'admin') {
      navigate('/admin');
    } else {
      navigate('/profile');
    }
    setUserDropdownOpen(false);
    setMobileMenuOpen(false);
  };

  const handleNotificationsClick = () => {
    navigate('/notifications');
    setHasNotifications(false);
  };

  return (
    <header className="sticky top-0 z-50 w-full border-b border-neutral-200 dark:border-neutral-800 bg-white/95 dark:bg-neutral-950/95 backdrop-blur-md transition-colors duration-300">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">

          {/* Logo avec lien vers home */}
          <div className="flex items-center space-x-4">
            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="lg:hidden p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800"
              aria-label="Menu"
            >
              {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>

            <Link to="/" className="flex items-center space-x-2">
              <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
                <span className="font-bold text-white">AI</span>
              </div>
              <span className="text-xl font-bold text-neutral-900 dark:text-white hidden sm:block">
                Mpanolo<span className="text-primary-600 dark:text-primary-400">Tsaina</span>
              </span>
            </Link>
          </div>

          {/* Barre de recherche - Desktop */}
          <div className="hidden lg:flex flex-1 max-w-2xl mx-8">
            <form onSubmit={handleSearch} className="relative w-full">
              <div className="relative">
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t('search_placeholder') || "Hikaroka vaovao, fanabeazana, sns..."}
                  className="w-full px-4 pl-10 py-2 rounded-full border border-neutral-300 dark:border-neutral-700 bg-neutral-50 dark:bg-neutral-900 text-neutral-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-300"
                />
                <Search 
                  className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-500 dark:text-neutral-400" 
                  size={18} 
                />
                {searchQuery && (
                  <button
                    type="button"
                    onClick={handleClearSearch}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-neutral-500 dark:text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-300"
                  >
                    <X size={18} />
                  </button>
                )}
              </div>

              {/* Suggestions de recherche */}
              {searchSuggestions.length > 0 && (
                <div className="absolute top-full mt-1 w-full bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg shadow-lg z-40 overflow-hidden">
                  <div className="py-2">
                    <div className="px-3 py-1 text-xs font-medium text-neutral-500 dark:text-neutral-400">
                      {t('popular_searches') || "Hikaroka malaza"}
                    </div>
                    {searchSuggestions.map((suggestion, index) => (
                      <button
                        key={index}
                        type="button"
                        onClick={() => handleSearchSuggestionClick(suggestion)}
                        className="w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 text-neutral-700 dark:text-neutral-300 transition-colors"
                      >
                        <div className="flex items-center space-x-2">
                          <Search size={14} className="text-neutral-400" />
                          <span className="text-sm">{suggestion}</span>
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </form>
          </div>

          {/* Actions: Notifications, Langue, Thème, Authentification */}
          <div className="flex items-center space-x-2">

            {/* Bouton recherche mobile */}
            <button
              onClick={() => setShowSearchBar(!showSearchBar)}
              className="lg:hidden p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800"
              aria-label="Search"
            >
              <Search size={20} />
            </button>

            {/* Notifications (si authentifié) */}
            {isAuthenticated && (
              <button
                onClick={handleNotificationsClick}
                className="relative p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800"
                aria-label="Notifications"
              >
                <Bell size={20} />
                {hasNotifications && (
                  <span className="absolute top-1 right-1 h-2 w-2 bg-red-500 rounded-full"></span>
                )}
              </button>
            )}

            {/* Sélecteur de langue */}
            <div className="relative">
              <button
                onClick={() => {
                  setLanguageDropdownOpen(!languageDropdownOpen);
                  setThemeDropdownOpen(false);
                  setUserDropdownOpen(false);
                }}
                className="flex items-center space-x-1 px-3 py-2 rounded-lg border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
                aria-label={t('language')}
              >
                <Globe size={18} className="text-neutral-600 dark:text-neutral-400" />
                <span className="font-medium text-neutral-700 dark:text-neutral-300 hidden sm:inline">
                  {language === 'en' ? 'EN' : language === 'fr' ? 'FR' : 'MG'}
                </span>
                <ChevronDown size={16} className="text-neutral-500 hidden sm:block" />
              </button>

              {/* Dropdown langue */}
              {languageDropdownOpen && (
                <div className="absolute right-0 mt-2 w-40 py-2 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg shadow-lg z-50">
                  <button
                    onClick={() => changeLanguage('en')}
                    className={`w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors ${language === 'en' ? 'text-primary-600 dark:text-primary-400 font-medium' : 'text-neutral-700 dark:text-neutral-300'}`}
                  >
                    <div className="flex items-center space-x-2">
                      <span className="text-sm">🇺🇸</span>
                      <span>English</span>
                    </div>
                  </button>
                  <button
                    onClick={() => changeLanguage('fr')}
                    className={`w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors ${language === 'fr' ? 'text-primary-600 dark:text-primary-400 font-medium' : 'text-neutral-700 dark:text-neutral-300'}`}
                  >
                    <div className="flex items-center space-x-2">
                      <span className="text-sm">🇫🇷</span>
                      <span>Français</span>
                    </div>
                  </button>
                  <button
                    onClick={() => changeLanguage('mg')}
                    className={`w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors ${language === 'mg' ? 'text-primary-600 dark:text-primary-400 font-medium' : 'text-neutral-700 dark:text-neutral-300'}`}
                  >
                    <div className="flex items-center space-x-2">
                      <span className="text-sm">🇲🇬</span>
                      <span>Malagasy</span>
                    </div>
                  </button>
                </div>
              )}
            </div>

            {/* Sélecteur de thème */}
            <div className="relative hidden sm:block">
              <button
                onClick={() => {
                  setThemeDropdownOpen(!themeDropdownOpen);
                  setLanguageDropdownOpen(false);
                  setUserDropdownOpen(false);
                }}
                className="flex items-center space-x-1 px-3 py-2 rounded-lg border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
                aria-label={t('theme')}
              >
                {darkMode ? (
                  <Moon size={18} className="text-neutral-600 dark:text-neutral-400" />
                ) : (
                  <Sun size={18} className="text-neutral-600 dark:text-neutral-400" />
                )}
                <ChevronDown size={16} className="text-neutral-500" />
              </button>

              {/* Dropdown thème */}
              {themeDropdownOpen && (
                <div className="absolute right-0 mt-2 w-40 py-2 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg shadow-lg z-50">
                  <button
                    onClick={() => changeTheme('light')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <Sun size={16} />
                    <span>{t('light')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('dark')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <Moon size={16} />
                    <span>{t('dark')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('system')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <div className="flex items-center">
                      <Sun size={14} className="mr-[-2px]" />
                      <Moon size={14} className="ml-[-2px]" />
                    </div>
                    <span>{t('system')}</span>
                  </button>
                </div>
              )}
            </div>

            {/* Bouton mode sombre/clair (version simple pour mobile) */}
            <button
              onClick={toggleDarkMode}
              className="sm:hidden p-2 rounded-lg border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
              aria-label={t('theme')}
            >
              {darkMode ? (
                <Moon size={20} className="text-neutral-600 dark:text-neutral-400" />
              ) : (
                <Sun size={20} className="text-neutral-600 dark:text-neutral-400" />
              )}
            </button>

            {/* Boutons d'authentification ou profil utilisateur */}
            {isAuthenticated ? (
              <div className="relative">
                <button
                  onClick={() => {
                    setUserDropdownOpen(!userDropdownOpen);
                    setLanguageDropdownOpen(false);
                    setThemeDropdownOpen(false);
                  }}
                  className="flex items-center space-x-2 px-4 py-2 rounded-lg bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 text-white font-medium transition-all duration-300 hover:shadow-lg hover:shadow-primary-500/25"
                >
                  <div className="h-7 w-7 rounded-full bg-white/30 flex items-center justify-center">
                    <span className="text-xs font-bold">{userName.charAt(0).toUpperCase()}</span>
                  </div>
                  <span className="hidden md:inline text-sm">{userName}</span>
                  <ChevronDown size={16} className="hidden sm:block" />
                </button>

                {/* Dropdown utilisateur */}
                {userDropdownOpen && (
                  <div className="absolute right-0 mt-2 w-56 py-2 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg shadow-lg z-50">
                    <div className="px-4 py-2 border-b border-neutral-200 dark:border-neutral-800">
                      <p className="text-sm font-medium text-neutral-900 dark:text-white">{userName}</p>
                      <p className="text-xs text-neutral-600 dark:text-neutral-400 truncate">{userEmail}</p>
                    </div>
                    <button
                      onClick={handleDashboardClick}
                      className="flex items-center space-x-3 px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300 w-full"
                    >
                      <User size={16} />
                      <span>{currentUser?.role === 'admin' ? t('dashboard') : t('profile')}</span>
                    </button>
                    <button
                      onClick={handleNotificationsClick}
                      className="flex items-center space-x-3 px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300 w-full"
                    >
                      <Bell size={16} />
                      <span>{t('notifications')}</span>
                      {hasNotifications && (
                        <span className="h-2 w-2 bg-red-500 rounded-full ml-auto"></span>
                      )}
                    </button>
                    <div className="border-t border-neutral-200 dark:border-neutral-800 my-1"></div>
                    <button
                      onClick={handleLogout}
                      className="w-full text-left flex items-center space-x-3 px-4 py-2 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors text-red-600 dark:text-red-400"
                    >
                      <LogIn size={16} />
                      <span>{t('logout')}</span>
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="flex items-center space-x-2">
                <button
                  onClick={handleLoginClick}
                  className="hidden md:flex items-center space-x-2 px-4 py-2 rounded-lg border border-primary-500 text-primary-600 dark:text-primary-400 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors"
                >
                  <LogIn size={18} />
                  <span>{t('login')}</span>
                </button>
                <button
                  onClick={handleRegisterClick}
                  className="flex items-center space-x-2 px-4 py-2 rounded-lg bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 text-white font-medium transition-all duration-300 hover:shadow-lg hover:shadow-primary-500/25"
                >
                  <UserPlus size={18} className="hidden sm:block" />
                  <span className="hidden sm:inline">{t('register')}</span>
                  <span className="sm:hidden text-sm">Inscrire</span>
                </button>
              </div>
            )}
          </div>
        </div>

        {/* Barre de recherche mobile (affichée conditionnellement) */}
        {showSearchBar && (
          <div className="lg:hidden py-3 border-t border-neutral-200 dark:border-neutral-800 animate-slide-down">
            <form onSubmit={handleSearch} className="relative">
              <div className="relative">
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t('search_placeholder') || "Hikaroka vaovao, fanabeazana, sns..."}
                  className="w-full px-4 pl-10 py-3 rounded-lg border border-neutral-300 dark:border-neutral-700 bg-neutral-50 dark:bg-neutral-900 text-neutral-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-300"
                  autoFocus
                />
                <Search 
                  className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-500 dark:text-neutral-400" 
                  size={20} 
                />
                {searchQuery && (
                  <button
                    type="button"
                    onClick={handleClearSearch}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-neutral-500 dark:text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-300"
                  >
                    <X size={20} />
                  </button>
                )}
              </div>

              {/* Suggestions de recherche mobile */}
              {searchSuggestions.length > 0 && (
                <div className="absolute top-full mt-1 w-full bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg shadow-lg z-40 overflow-hidden">
                  <div className="py-2">
                    <div className="px-3 py-1 text-xs font-medium text-neutral-500 dark:text-neutral-400">
                      {t('popular_searches') || "Hikaroka malaza"}
                    </div>
                    {searchSuggestions.map((suggestion, index) => (
                      <button
                        key={index}
                        type="button"
                        onClick={() => handleSearchSuggestionClick(suggestion)}
                        className="w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 text-neutral-700 dark:text-neutral-300 transition-colors"
                      >
                        <div className="flex items-center space-x-2">
                          <Search size={14} className="text-neutral-400" />
                          <span className="text-sm">{suggestion}</span>
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </form>
          </div>
        )}

        {/* Navigation Desktop */}
        <nav className="hidden lg:flex items-center justify-center space-x-1 py-2 border-t border-neutral-200 dark:border-neutral-800">
          {navItems.map((item) => (
            <Link
              key={item.key}
              to={item.path}
              className="px-4 py-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-all duration-200 font-medium text-sm"
            >
              {t(item.key)}
            </Link>
          ))}
        </nav>

        {/* Menu Mobile complet */}
        {mobileMenuOpen && (
          <div className="lg:hidden py-4 border-t border-neutral-200 dark:border-neutral-800 animate-slide-up">
            <div className="flex flex-col space-y-2">
              {navItems.map((item) => (
                <Link
                  key={item.key}
                  to={item.path}
                  className="px-4 py-3 rounded-lg text-neutral-700 dark:text-neutral-300 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-all duration-200 font-medium"
                  onClick={() => setMobileMenuOpen(false)}
                >
                  {t(item.key)}
                </Link>
              ))}

              {/* Boutons d'authentification pour mobile */}
              {!isAuthenticated ? (
                <>
                  <button
                    onClick={handleLoginClick}
                    className="flex items-center justify-center space-x-2 px-4 py-3 rounded-lg border border-primary-500 text-primary-600 dark:text-primary-400 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors mt-4"
                  >
                    <LogIn size={18} />
                    <span>{t('login')}</span>
                  </button>
                  <button
                    onClick={handleRegisterClick}
                    className="flex items-center justify-center space-x-2 px-4 py-3 rounded-lg bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 text-white font-medium transition-all duration-300"
                  >
                    <UserPlus size={18} />
                    <span>{t('register')}</span>
                  </button>
                </>
              ) : (
                <>
                  <div className="pt-4 border-t border-neutral-200 dark:border-neutral-800">
                    <div className="flex items-center space-x-3 px-4 py-3">
                      <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
                        <span className="font-bold text-white">{userName.charAt(0).toUpperCase()}</span>
                      </div>
                      <div>
                        <p className="font-medium text-neutral-900 dark:text-white">{userName}</p>
                        <p className="text-sm text-neutral-600 dark:text-neutral-400">{userEmail}</p>
                      </div>
                    </div>
                  </div>
                  <button
                    onClick={handleDashboardClick}
                    className="flex items-center space-x-3 px-4 py-3 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <User size={16} />
                    <span>{currentUser?.role === 'admin' ? t('dashboard') : t('profile')}</span>
                  </button>
                  <button
                    onClick={handleNotificationsClick}
                    className="flex items-center space-x-3 px-4 py-3 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <Bell size={16} />
                    <span>{t('notifications')}</span>
                    {hasNotifications && (
                      <span className="h-2 w-2 bg-red-500 rounded-full ml-auto"></span>
                    )}
                  </button>
                  <button
                    onClick={handleLogout}
                    className="flex items-center justify-center space-x-3 px-4 py-3 rounded-lg border border-red-500 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors mt-4"
                  >
                    <LogIn size={18} />
                    <span>{t('logout')}</span>
                  </button>
                </>
              )}

              {/* Options de thème pour mobile */}
              <div className="pt-4 border-t border-neutral-200 dark:border-neutral-800">
                <div className="flex flex-col space-y-2">
                  <div className="px-4 py-2 text-sm font-medium text-neutral-500 dark:text-neutral-400">
                    {t('theme')}
                  </div>
                  <button
                    onClick={() => changeTheme('light')}
                    className="flex items-center space-x-3 px-4 py-2 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors"
                  >
                    <Sun size={18} className="text-neutral-600 dark:text-neutral-400" />
                    <span className="text-neutral-700 dark:text-neutral-300">{t('light')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('dark')}
                    className="flex items-center space-x-3 px-4 py-2 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors"
                  >
                    <Moon size={18} className="text-neutral-600 dark:text-neutral-400" />
                    <span className="text-neutral-700 dark:text-neutral-300">{t('dark')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('system')}
                    className="flex items-center space-x-3 px-4 py-2 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors"
                  >
                    <div className="flex items-center">
                      <Sun size={14} className="mr-[-2px] text-neutral-600 dark:text-neutral-400" />
                      <Moon size={14} className="ml-[-2px] text-neutral-600 dark:text-neutral-400" />
                    </div>
                    <span className="text-neutral-700 dark:text-neutral-300">{t('system')}</span>
                  </button>
                </div>
              </div>

              {/* Recherches populaires pour mobile */}
              <div className="pt-4 border-t border-neutral-200 dark:border-neutral-800">
                <div className="flex flex-col space-y-2">
                  <div className="px-4 py-2 text-sm font-medium text-neutral-500 dark:text-neutral-400">
                    {t('popular_searches') || "Hikaroka malaza"}
                  </div>
                  {popularSearches[language]?.slice(0, 3).map((search, index) => (
                    <button
                      key={index}
                      onClick={() => {
                        setSearchQuery(search);
                        navigate(`/search?q=${encodeURIComponent(search)}`);
                        setMobileMenuOpen(false);
                      }}
                      className="flex items-center space-x-3 px-4 py-2 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-left"
                    >
                      <Search size={14} className="text-neutral-400" />
                      <span className="text-sm text-neutral-700 dark:text-neutral-300">{search}</span>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
